#!/usr/bin/env python3
"""Small, isolated AOT API observations; never executes generated guest code."""
import hashlib,json,os,pathlib,subprocess,sys,tempfile,time

ROOT=pathlib.Path(__file__).resolve().parent
OUT=pathlib.Path(sys.argv[1]).resolve();OUT.mkdir(parents=True,exist_ok=True)
r=dict(status='running',commands=[],probes=[],limitations=[
    'Private API signatures reconstructed from exported C++ mangling and cited public research.',
    'Synthetic thread-context/runtime offsets; no executable process ABI validation.',
    'Generated bytes have unapplied fixups and may contain data/metadata, not just instructions.',
    'Raw object disassembly does not establish function boundaries or semantic correctness.',
    'No hooks, task attachment, SIP changes, protected cache access or Apple binary export.'])
def save():(OUT/'aot-manifest.json').write_text(json.dumps(r,indent=2)+'\n')
def run(name,command,timeout=20):
    start=time.monotonic()
    try:
        p=subprocess.run([str(x) for x in command],text=True,capture_output=True,timeout=timeout)
        row=dict(name=name,returncode=p.returncode,seconds=time.monotonic()-start)
        stdout,stderr=p.stdout,p.stderr
    except subprocess.TimeoutExpired as e:
        row=dict(name=name,returncode=124,timeout=timeout)
        def decode(x):return x.decode(errors='replace') if isinstance(x,bytes) else (x or '')
        stdout,stderr=decode(e.stdout),decode(e.stderr)
    for suffix,text in [('stdout',stdout),('stderr',stderr)]:
        text=text.replace(str(pathlib.Path.home()),'<HOME>')
        (OUT/(name+'.'+suffix+'.txt')).write_text(text[:262144])
        if len(text)>262144:row['truncated']=True
    r['commands'].append(row);save()
    if row['returncode']:raise RuntimeError(name+' failed: '+stderr[-800:])
    return stdout
try:
    r['os']=run('os',['/usr/bin/sw_vers'])
    r['architecture']=run('arch',['/usr/bin/uname','-m']).strip()
    if r['architecture']!='arm64':raise RuntimeError('ARM64 runner required')
    library=pathlib.Path('/Library/Apple/usr/lib/libRosettaAot.dylib')
    r['library_path']=str(library)
    r['backing_file_present']=library.is_file()
    if library.is_file():
        r['library_sha256']=hashlib.sha256(library.read_bytes()).hexdigest()
        run('library-signature',['/usr/bin/codesign','-dv','--verbose=4',library])
    with tempfile.TemporaryDirectory(prefix='attesor-aot-',dir=os.environ.get('RUNNER_TEMP')) as tmp:
        d=pathlib.Path(tmp);binary=d/'probe'
        run('compile',['/usr/bin/clang++','-std=c++17','-arch','arm64','-O2','-Wall','-Wextra',ROOT/'aot_probe.cpp','-o',binary],timeout=60)
        for case in ['arith','flags','fpchain','loop']:
            blob=d/(case+'.arm64')
            stdout=run(case,[binary,case,'translate',blob])
            if 'PROBE_OK' not in stdout or 'GENERATED_BYTES' not in stdout:raise RuntimeError('incomplete probe '+case)
            ir=stdout.split('IR_BEGIN',1)[1].split('IR_END',1)[0].strip()
            if len(ir)<20:raise RuntimeError('empty/unproven IR '+case)
            data=blob.read_bytes()
            if not 4<=len(data)<=65536:raise RuntimeError('generated byte budget '+case)
            r['probes'].append(dict(case=case,generated_bytes=len(data),sha256=hashlib.sha256(data).hexdigest(),
                ir_text_nonempty=True,generated_code_executed=False,fixups_applied=False));save()
            # The object contains only the translation of OUR small probe.
            asm=d/(case+'.s');obj=d/(case+'.o')
            asm.write_text('.section __TEXT,__text,regular,pure_instructions\n.globl _own_probe\n_own_probe:\n.incbin "'+str(blob)+'"\n')
            run(case+'-object',['/usr/bin/clang','-arch','arm64','-c',asm,'-o',obj])
            run(case+'-raw-disassembly',['/usr/bin/otool','-tvV',obj])
    r['status']='observations_completed';save()
except BaseException as e:r.update(status='failed',error=str(e));save();raise
